import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiMail, FiCheckCircle, FiTrash2, FiEye } from 'react-icons/fi';
import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminCard from '../common/AdminCard';
import AdminModal from '../common/AdminModal';

const AdminMessages = () => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);

  useEffect(() => {
    fetchMessages();
  }, []);

  const fetchMessages = async () => {
    try {
      const response = await api.get('/api/contact/');
      setMessages(response.data);
    } catch (error) {
      toast.error('Failed to load messages');
    } finally {
      setLoading(false);
    }
  };

  const handleMarkRead = async (id) => {
    try {
      await api.put(`/api/contact/${id}/read`);
      toast.success('Message marked as read');
      fetchMessages();
    } catch (error) {
      toast.error('Failed to mark message as read');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this message?')) {
      try {
        await api.delete(`/api/contact/${id}`);
        toast.success('Message deleted successfully');
        fetchMessages();
      } catch (error) {
        toast.error('Failed to delete message');
      }
    }
  };

  const handleView = (message) => {
    setSelectedMessage(message);
    setModalOpen(true);
    if (!message.is_read) {
      handleMarkRead(message.id);
    }
  };

  const columns = [
    {
      key: 'is_read',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${
          val ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'
        }`}>
          {val ? 'Read' : 'Unread'}
        </span>
      ),
    },
    { key: 'name', label: 'Name' },
    { key: 'email', label: 'Email' },
    { key: 'subject', label: 'Subject' },
    {
      key: 'created_at',
      label: 'Date',
      render: (val) => new Date(val).toLocaleString(),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleView(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEye />
          </button>
          {!row.is_read && (
            <button
              onClick={() => handleMarkRead(row.id)}
              className="text-green-600 hover:text-green-800"
            >
              <FiCheckCircle />
            </button>
          )}
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Messages</h1>
        <div className="flex items-center space-x-2">
          <span className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-sm">
            {messages.filter(m => !m.is_read).length} Unread
          </span>
          <span className="bg-gray-100 text-gray-800 px-3 py-1 rounded-full text-sm">
            {messages.length} Total
          </span>
        </div>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={messages}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setSelectedMessage(null);
        }}
        title="Message Details"
      >
        {selectedMessage && (
          <div className="space-y-4">
            <div>
              <label className="font-semibold text-gray-700">From:</label>
              <p className="text-gray-900">{selectedMessage.name}</p>
            </div>
            <div>
              <label className="font-semibold text-gray-700">Email:</label>
              <p className="text-gray-900">{selectedMessage.email}</p>
            </div>
            {selectedMessage.phone && (
              <div>
                <label className="font-semibold text-gray-700">Phone:</label>
                <p className="text-gray-900">{selectedMessage.phone}</p>
              </div>
            )}
            <div>
              <label className="font-semibold text-gray-700">Subject:</label>
              <p className="text-gray-900">{selectedMessage.subject || 'No subject'}</p>
            </div>
            <div>
              <label className="font-semibold text-gray-700">Message:</label>
              <p className="text-gray-900 bg-gray-50 p-4 rounded-lg whitespace-pre-wrap">
                {selectedMessage.message}
              </p>
            </div>
            <div>
              <label className="font-semibold text-gray-700">Received:</label>
              <p className="text-gray-900">
                {new Date(selectedMessage.created_at).toLocaleString()}
              </p>
            </div>
            <div className="flex justify-end">
              <button
                onClick={() => {
                  setModalOpen(false);
                  setSelectedMessage(null);
                }}
                className="admin-btn-secondary"
              >
                Close
              </button>
            </div>
          </div>
        )}
      </AdminModal>
    </div>
  );
};

export default AdminMessages;
